steps = [
    step("登录接口限流的第一种写法:每个 IP 每分钟 3 次,不管成败都计数。同一个 IP 连续 5 次正确登录:[200, 200, 200, 429, 429]——第 4 次起,连正常用户的成功登录也被挡住。", t=tl(S(1)), mark=lidx(S(1), '连续 5 次'), kv=KV([['成败都计数', '正常用户也会被挡']], ['成败都计数'])),
    step("只计算失败的尝试(Flask-Limiter 的 deduct_when,响应不是 200 才扣额度):连续 5 次正确登录都是 200(成功不占额度);同一个 IP 连续 4 次错误密码是 [401, 401, 401, 429],失败累计到 3 次后第 4 次被限流;之后用正确的密码登录也是 429——限流在密码校验之前生效,被挡住的时候即使密码对也进不去。", t=tl(S(2)), done=lidx(S(2), '5 次正确登录'), mark=lidx(S(2), '4 次错误密码', '之后用正确的密码'), kv=KV([['deduct_when', '只有失败的才扣额度'], ['被限流时', '正确的密码也进不去']], ['deduct_when'])),
    step("按用户名限流(key_func 取请求里的用户名):对 ann 用 5 个不同的 IP 各猜 1 次,结果 [401, 401, 401, 429, 429]——换 IP 也挡得住对同一个账号的连续猜测;bob 用同样的 IP 登录仍是 200,别的账号不受影响。副作用是:真正的 ann 此时也被挡住(429)——任何人都能故意输错来让某个账号暂时无法登录。", t=tl(S(3)), done=lidx(S(3), 'bob 用同样'), mark=lidx(S(3), '5 个不同的 IP', '真正的 ann'), kv=KV([['按用户名', '换 IP 也挡得住'], ['副作用', '账号可被人为锁住']], ['副作用'])),
    step("两层叠加:每个用户名 3 次失败加每个 IP 10 次失败。同一个 IP 猜 ann 4 次是 [401, 401, 401, 429](用户名那层生效);同一个 IP 再换 10 个不同的用户名各猜 1 次是 [401×7, 429, 429, 429]——加上前面对 ann 的 3 次失败,这个 IP 累计 10 次失败后被 IP 那层挡住。两层互补:用户名层防针对一个账号的猜测,IP 层防一个来源横扫很多账号。", t=tl(S(4)), done=lidx(S(4), '猜 ann 4 次'), mark=lidx(S(4), '换 10 个不同的用户名'), kv=KV([['用户名层', '防针对单个账号'], ['IP 层', '防一个来源横扫多个账号']], ['IP 层'])),
    step("被限流时的响应:第 4 次是 429 与 HTML 的「429 Too Many Requests」页面,响应里没有 Retry-After 与 X-RateLimit-* 头——因为我把 RATELIMIT_HEADERS_ENABLED 设在 Limiter 已经初始化之后,配置在 init_app 时读一次,之后再改不生效(和第 71 篇看到的现象一致)。要这些头必须在构造 Limiter 之前配置(第 76 篇里用 headers_enabled=True 构造参数的写法是有头的)。JSON 接口还要自己注册 429 的 errorhandler 返回 JSON。", t=tl(S(5)), mark=lidx(S(5), '第 4 次'), kv=KV([['配置读取时机', 'init_app 时读一次'], ['429 默认', 'HTML 页面,没有 Retry-After']], ['配置读取时机'])),
]
